import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type NoteCategory = 'Password' | 'ToDo' | 'Idea' | 'General' | 'Personal';

export interface Note {
  id: string;
  title: string;
  content: string;
  category: NoteCategory;
  isPrivate: boolean;
  createdAt: number;
  updatedAt: number;
}

export type Theme = 'light' | 'dark';

export interface AppState {
  notes: Note[];
  theme: Theme;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const categorizeNote = async (content: string): Promise<{ category: string; summary: string }> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analyze the following note content and suggest the best category (choose one from: Password, ToDo, Idea, General, Personal) and a very brief summary (max 10 words). Note content: "${content}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: { type: Type.STRING },
            summary: { type: Type.STRING },
          },
          required: ["category", "summary"],
        },
      },
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("AI Categorization failed:", error);
    return { category: 'General', summary: '' };
  }
};

