import { NoteCard } from './components/NoteCard';
import { NoteEditor } from './components/NoteEditor';

const App: React.FC = () => {
  const [notes, setNotes] = useState<Note[]>([]);
  const [theme, setTheme] = useState<Theme>('light');
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editingNote, setEditingNote] = useState<Note | null>(null);
  const [filter, setFilter] = useState<NoteCategory | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');

  // Initial load
  useEffect(() => {
    const savedNotes = localStorage.getItem('notekita_notes');
    const savedTheme = localStorage.getItem('notekita_theme') as Theme;

    if (savedNotes) setNotes(JSON.parse(savedNotes));
    if (savedTheme) {
      setTheme(savedTheme);
      document.documentElement.classList.toggle('dark', savedTheme === 'dark');
    }
  }, []);

  // Sync with localStorage
  useEffect(() => {
    localStorage.setItem('notekita_notes', JSON.stringify(notes));
  }, [notes]);

  useEffect(() => {
    localStorage.setItem('notekita_theme', theme);
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'light' ? 'dark' : 'light'));
  };

  const saveNote = (noteData: Omit<Note, 'id' | 'createdAt' | 'updatedAt'> & { id?: string }) => {
    const now = Date.now();
    if (noteData.id) {
      // Update
      setNotes(prev => prev.map(n => 
        n.id === noteData.id 
          ? { ...n, ...noteData, updatedAt: now } 
          : n
      ));
    } else {
      // Create
      const newNote: Note = {
        id: crypto.randomUUID(),
        ...noteData,
        createdAt: now,
        updatedAt: now,
      };
      setNotes(prev => [newNote, ...prev]);
    }
    setEditingNote(null);
  };

  const deleteNote = (id: string) => {
    if (window.confirm('Hapus catatan ini selamanya?')) {
      setNotes(prev => prev.filter(n => n.id !== id));
    }
  };

  const filteredNotes = useMemo(() => {
    return notes
      .filter(n => filter === 'All' || n.category === filter)
      .filter(n => 
        n.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
        n.content.toLowerCase().includes(searchQuery.toLowerCase())
